import os
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

# Whitelist of allowed characters for safe evaluation
ALLOWED_CHARS = re.compile(r'^[0-9+\-*/.()% ]+$')

@app.route('/calculator', methods=['POST'])
def calculate():
    data = request.get_json(silent=True)
    if not data or 'expression' not in data:
        return jsonify({"error": "Invalid input"}), 400

    expression = data.get('expression')
    if not isinstance(expression, str) or not expression.strip():
        return jsonify({"error": "Invalid input"}), 400

    # Sanitize: only allow digits and basic operators
    if not ALLOWED_CHARS.match(expression):
        return jsonify({"error": "Invalid input"}), 400

    # Further safety: ensure no double operators or weird patterns
    # Allow basic arithmetic only
    try:
        # Using a restricted eval environment
        result = str(eval(expression, {"__builtins__": None}, {}))
        return jsonify({"result": result}), 200
    except ZeroDivisionError:
        return jsonify({"error": "Division by zero"}), 400
    except Exception as e:
        return jsonify({"error": "Invalid expression"}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
